    @(negedge clk_i); rst_in=1; shift_i=1; din_i=2'b01; @(posedge clk_i); #1;
    assert(pc_o==32'h77ab_6fbb) else $fatal(1,"PC serial shift mismatch");
    $display("FazyRV program counter smoke test passed"); $finish;
